(function(){
  function parseCsv(text){
    text=String(text==null?'':text).replace(/\r\n|\r/g,'\n');
    var rows=[], row=[], field='', i=0, q=false;
    while(i<text.length){ var c=text[i];
      if(q){ if(c==='"'){ if(text[i+1]==='"'){field+='"';i++;} else q=false; } else field+=c; }
      else { if(c==='"') q=true;
        else if(c===','){ row.push(field); field=''; }
        else if(c==='\n'){ row.push(field); rows.push(row); row=[]; field=''; }
        else field+=c; }
      i++; }
    if(field!==''||row.length){ row.push(field); rows.push(row); }
    return rows;
  }
  function toJson(csv){
    var rows=parseCsv(csv); if(rows.length<1) return {value:'[]'};
    var head=rows[0], out=[];
    for(var r=1;r<rows.length;r++){ var o={}; for(var c=0;c<head.length;c++){ o[head[c]]= rows[r][c]===undefined?'':rows[r][c]; } out.push(o); }
    return {value:JSON.stringify(out,null,2)};
  }
  function csvCell(v){ v=String(v==null?'':v); if(/[",\n]/.test(v)) return '"'+v.replace(/"/g,'""')+'"'; return v; }
  function toCsv(json){
    var arr; try{ arr=JSON.parse(json); }catch(e){ return {error:'JSON 解析失败: '+e.message}; }
    if(!Array.isArray(arr)||arr.length===0) return {value:''};
    var keys=Object.keys(arr[0]); var lines=[keys.map(csvCell).join(',')];
    arr.forEach(function(o){ lines.push(keys.map(function(k){return csvCell(o[k]);}).join(',')); });
    return {value:lines.join('\n')};
  }
  var API={toJson:toJson,toCsv:toCsv,parseCsv:parseCsv};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__CsvJsonForge__=API;
})();
